package com.doulala.android;
import android.app.*;import android.content.*;import android.os.Bundle;import android.text.*;import android.widget.*;import java.util.concurrent.*;
/** Compact catalog for 64 isolated account spaces. */
public final class MainActivity extends Activity {
 private SharedPreferences settings; private LinearLayout catalog,archivedList,root; private EditText search; private final ExecutorService resetWorker=Executors.newSingleThreadExecutor(); private volatile boolean resetRunning;
 public static final String[] SITES={"Dola","豆包","即梦","千问","云雀"}; public static final String[] URLS={"https://www.dola.com/","https://www.doubao.com/chat/","https://jimeng.jianying.com/","https://www.qianwen.com/","https://yunq.jianying.com/"};
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.setup(this);settings=getSharedPreferences("catalog",MODE_PRIVATE);ensureInitialCatalog();render();offerPendingRecovery();handleResetIntent(getIntent());}
 @Override public void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleResetIntent(intent);}
 @Override protected void onDestroy(){resetWorker.shutdownNow();super.onDestroy();}
 private void ensureInitialCatalog(){if(!settings.getBoolean("catalogInitialized",false)){SharedPreferences.Editor e=settings.edit().putBoolean("catalogInitialized",true);if(!settings.contains("enabled0")&&!settings.getBoolean("deleted0",false))e.putBoolean("enabled0",true);e.commit();}}
 private void offerPendingRecovery(){for(int i=0;i<SpaceSlots.COUNT;i++)if(SpaceReset.isPending(this,i)){final int slot=i;new AlertDialog.Builder(this).setTitle("空间清理等待重试").setMessage("SPACE "+(slot+1)+" 的登录数据仍被锁定；未完成前不会打开该空间，也不会影响其它空间。").setNegativeButton("稍后",null).setPositiveButton("重试清理",(d,w)->runReset(slot,SpaceReset.pendingOperation(this,slot))).show();return;}}
 private void render(){migrateRetiredSpaceState();LinearLayout shell=Ui.column(this);shell.setBackgroundColor(Ui.BG);LinearLayout fixed=Ui.column(this);Ui.pad(fixed,14);fixed.addView(Ui.text(this,"DOULALA  /  ANDROID",11,Ui.ACCENT));fixed.addView(Ui.title(this,"账号空间",24));fixed.addView(Ui.text(this,"64 个独立空间 · Cookie、网页存储、标签和缓存彼此隔离",13,Ui.MUTED));search=Ui.edit(this,"搜索空间名称、编号或站点","");fixed.addView(search);LinearLayout actions=Ui.row(this);Ui.equal(actions,Ui.button(this,"＋ 新建独立空间",this::openFirstReusable));Ui.equal(actions,Ui.button(this,"创作工作台",()->startActivity(new Intent(this,StudioActivity.class))));fixed.addView(actions);shell.addView(fixed,new LinearLayout.LayoutParams(-1,-2));LinearLayout content=Ui.column(this);content.setPadding(0,0,Ui.dp(this,14),Ui.dp(this,14));catalog=Ui.column(this);content.addView(catalog);archivedList=Ui.column(this);Ui.pad(archivedList,2);content.addView(Ui.title(this,"已归档空间",18));content.addView(Ui.text(this,"归档只隐藏入口，不清除原网页登录态或本机数据。",12,Ui.MUTED));content.addView(archivedList);content.addView(Ui.button(this,"移植范围与使用说明",this::about));content.addView(Ui.text(this,"数据保存在本机 · 不自动同步桌面登录态\n第三方网页登录兼容性需真机验证。",12,Ui.MUTED));ScrollView scroll=Ui.scroll(this,content);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){refreshCatalog(s.toString());}public void afterTextChanged(Editable e){}});refreshCatalog("");setContentView(shell);}
private void refreshCatalog(String raw){String q=raw==null?"":raw.trim().toLowerCase(java.util.Locale.ROOT);catalog.removeAllViews();archivedList.removeAllViews();int archived=0;for(int i=0;i<SpaceSlots.COUNT;i++){final int slot=i;String name=settings.getString("name"+i,"创作空间 "+(i+1));String url=settings.getString("url"+i,URLS[0]);if(settings.getBoolean("enabled"+i,false)&&matches(q,name,url,i)){LinearLayout card=Ui.card(this);card.addView(Ui.text(this,String.format(java.util.Locale.ROOT,"SPACE %02d",i+1),11,Ui.ACCENT));card.addView(Ui.title(this,name,17));card.addView(Ui.text(this,url,12,Ui.MUTED));LinearLayout buttons=Ui.row(this);Button enter=Ui.button(this,"进入空间",()->open(slot));enter.setContentDescription("进入空间："+name);Ui.equal(buttons,enter);Ui.equal(buttons,Ui.button(this,"设置",()->edit(slot)));Ui.equal(buttons,Ui.button(this,"清理/删除",()->confirmSpaceMaintenance(slot)));if(slot!=0)Ui.equal(buttons,Ui.button(this,"归档",()->confirmArchiveSpace(slot)));card.addView(buttons);catalog.addView(card);}if(i>0&&settings.getBoolean("archived"+i,false)&&matches(q,settings.getString("archivedName"+i,"创作空间 "+(i+1)),settings.getString("archivedUrl"+i,URLS[0]),i)){archived++;LinearLayout card=Ui.card(this);card.addView(Ui.text(this,"已归档 · SPACE "+String.format(java.util.Locale.ROOT,"%02d",i+1),11,Ui.MUTED));card.addView(Ui.title(this,settings.getString("archivedName"+i,"创作空间 "+(i+1)),16));card.addView(Ui.text(this,settings.getString("archivedUrl"+i,URLS[0]),12,Ui.MUTED));final int s=slot;LinearLayout archivedButtons=Ui.row(this);Ui.equal(archivedButtons,Ui.button(this,"恢复此空间",()->confirmRestoreSpace(s)));Ui.equal(archivedButtons,Ui.button(this,"清理/删除",()->confirmSpaceMaintenance(s)));card.addView(archivedButtons);archivedList.addView(card);}}if(archived==0)archivedList.addView(Ui.text(this,q.isEmpty()?"暂无已归档空间":"没有匹配的归档空间",12,Ui.MUTED));}
 private boolean matches(String q,String name,String url,int slot){return q.isEmpty()||name.toLowerCase(java.util.Locale.ROOT).contains(q)||url.toLowerCase(java.util.Locale.ROOT).contains(q)||String.valueOf(slot+1).equals(q)||String.format(java.util.Locale.ROOT,"%02d",slot+1).equals(q);}
 private void openFirstReusable(){for(int i=0;i<SpaceSlots.COUNT;i++)if(!settings.getBoolean("enabled"+i,false)&&!settings.getBoolean("archived"+i,false)&&!settings.getBoolean("retired"+i,false)&&!SpaceReset.isPending(this,i)){edit(i);return;}Ui.toast(this,"64 个隔离名额均已占用（含归档空间）；请先恢复已有空间");}
 private void open(int slot){if(SpaceReset.isPending(this,slot)){offerPendingRecovery();return;}Intent i=new Intent();i.setClassName(this,SpaceSlots.className(slot));i.putExtra("title",settings.getString("name"+slot,"创作空间 "+(slot+1)));i.putExtra("home",settings.getString("url"+slot,URLS[0]));i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}
 private void migrateRetiredSpaceState(){SharedPreferences.Editor e=settings.edit();boolean changed=false;for(int i=1;i<SpaceSlots.COUNT;i++)if(settings.getBoolean("retired"+i,false)&&!settings.getBoolean("archived"+i,false)){e.putBoolean("archived"+i,true).putString("archivedName"+i,settings.getString("name"+i,"创作空间 "+(i+1))).putString("archivedUrl"+i,settings.getString("url"+i,URLS[0])).remove("retired"+i);changed=true;}if(changed)e.commit();}
 private void confirmArchiveSpace(int slot){String name=settings.getString("name"+slot,"创作空间 "+(slot+1));new AlertDialog.Builder(this).setTitle("归档账号空间？").setMessage("“"+name+"”会从主列表隐藏，但不会清除 Cookie、网页存储、标签、书签或下载。它仍占用一个名额。").setNegativeButton("取消",null).setPositiveButton("归档空间",(d,w)->{String url=settings.getString("url"+slot,URLS[0]);boolean saved=settings.edit().putBoolean("enabled"+slot,false).putBoolean("archived"+slot,true).putString("archivedName"+slot,name).putString("archivedUrl"+slot,url).remove("name"+slot).remove("url"+slot).commit();if(saved){Ui.toast(this,"空间已归档；本机数据保留，可随时恢复");render();}else Ui.toast(this,"归档失败；设置未更改");}).show();}
 private void confirmRestoreSpace(int slot){String name=settings.getString("archivedName"+slot,"创作空间 "+(slot+1));new AlertDialog.Builder(this).setTitle("恢复账号空间？").setMessage("恢复“"+name+"”会重新开放同一隔离空间，并恢复本机原有网页登录态、标签和数据。").setNegativeButton("取消",null).setPositiveButton("恢复",(d,w)->{boolean restored=settings.edit().putBoolean("enabled"+slot,true).putString("name"+slot,name).putString("url"+slot,settings.getString("archivedUrl"+slot,URLS[0])).remove("archived"+slot).remove("archivedName"+slot).remove("archivedUrl"+slot).commit();if(restored){Ui.toast(this,"原账号空间已恢复");render();}else Ui.toast(this,"恢复失败；归档数据仍保留");}).show();}
 /** Browser sends this only after its own menu action.  Main owns the second,
  * explicit confirmation and never performs a reset merely by opening itself. */
 private void handleResetIntent(Intent intent){
  if(intent==null||!intent.hasExtra(SpaceReset.EXTRA_RESET_SLOT))return;
  final int slot=intent.getIntExtra(SpaceReset.EXTRA_RESET_SLOT,-1);final String op=intent.getStringExtra(SpaceReset.EXTRA_RESET_OPERATION);
  intent.removeExtra(SpaceReset.EXTRA_RESET_SLOT);intent.removeExtra(SpaceReset.EXTRA_RESET_OPERATION);
  if(!SpaceReset.valid(slot)||!SpaceReset.isOperation(op)){Ui.toast(this,"无效的空间清理请求");return;}
  String name=settings.getString("name"+slot,"创作空间 "+(slot+1));boolean deleting=SpaceReset.OP_DELETE.equals(op);
  new AlertDialog.Builder(this).setTitle(deleting?"彻底删除账号空间？":"清理账号空间登录数据？")
   .setMessage("“"+name+"”的 Cookie、网页存储、标签、缓存和该空间的视频任务将被清除。下载到公共下载目录的文件不会删除。"+(deleting?"\n\n删除还会移除此空间条目并释放名额；此操作不可撤销。":"\n\n空间名称和首页会保留，但需要重新登录。"))
   .setNegativeButton("取消",null).setPositiveButton(deleting?"删除并释放名额":"清理并退出登录",(d,w)->runReset(slot,op)).show();
 }
 private void confirmSpaceMaintenance(final int slot){new AlertDialog.Builder(this).setTitle("管理 SPACE "+(slot+1)).setItems(new String[]{"清理登录数据，保留空间名称","彻底删除空间并释放名额"},(d,which)->{Intent request=new Intent();request.putExtra(SpaceReset.EXTRA_RESET_SLOT,slot);request.putExtra(SpaceReset.EXTRA_RESET_OPERATION,which==0?SpaceReset.OP_CLEAR:SpaceReset.OP_DELETE);handleResetIntent(request);}).show();}
 private void runReset(final int slot,final String op){
  if(resetRunning){Ui.toast(this,"已有清理任务正在运行");return;} resetRunning=true;
  Ui.toast(this,"正在关闭该空间并安全清理…");
  resetWorker.execute(()->{final boolean ok=SpaceReset.performBlocking(getApplicationContext(),slot,op);runOnUiThread(()->{resetRunning=false;if(isFinishing()||isDestroyed())return;if(ok){Ui.toast(this,SpaceReset.OP_DELETE.equals(op)?"空间已删除，名额已释放":"登录数据已清理；名称已保留");render();}else new AlertDialog.Builder(this).setTitle("空间尚未清理").setMessage("空间仍被锁定或部分文件尚未移除；请重试。其它空间不会被清理。").setNegativeButton("稍后",null).setPositiveButton("重试",(d,w)->runReset(slot,op)).show();});});
 }
 private void edit(int slot){if(SpaceReset.isPending(this,slot)){Ui.toast(this,"该空间正在清理，请先重试完成");return;}LinearLayout form=Ui.column(this);Ui.pad(form,10);EditText name=Ui.edit(this,"空间名称",settings.getString("name"+slot,"创作空间 "+(slot+1)));EditText url=Ui.edit(this,"HTTPS 首页",settings.getString("url"+slot,URLS[0]));url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);form.addView(name);form.addView(url);form.addView(Ui.button(this,"选择平台",()->new AlertDialog.Builder(this).setTitle("默认首页").setItems(SITES,(d,n)->url.setText(URLS[n])).show()));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("空间 "+(slot+1)+" 设置").setView(form).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String normalized=UrlRules.normalize(url.getText().toString());if(normalized==null||!normalized.startsWith("https://")){url.setError("请输入有效 HTTPS 地址");return;}String n=name.getText().toString().trim();if(n.isEmpty()||n.length()>60){name.setError("名称需为 1–60 字");return;}settings.edit().remove("deleted"+slot).putBoolean("enabled"+slot,true).putString("name"+slot,n).putString("url"+slot,normalized).apply();dialog.dismiss();render();}));dialog.show();}
 private void about(){new AlertDialog.Builder(this).setTitle("移植范围与使用说明").setMessage("已编写：64 个进程隔离账号空间、多标签与书签、上传文件、下载中心、快捷文本与分镜工作台；空间按需启动，不会同时常驻 64 个进程。\n\n限制：Android WebView 不能运行 Windows DLL 或 Chrome 扩展；旧版 JS 不执行，网页媒体观察需新增页面适配确认（非 CDP）。30 秒生成、视频接口和 Google 登录均需平台实际支持，WebView 登录不保证成功，本版不伪造授权或生成结果。\n\n网页登录兼容性需真机验证，若第三方不允许 WebView 登录，请通过官方客户端使用。无需 Root。").setPositiveButton("知道了",null).show();}
}


